head.script:
scwin.init = function() {
    /**
    	W_addDataSet(데이타리스트 아이디, 그리드뷰 아이디);
    **/
    var searchCol01 = "PROGRM_NM,PROGRM_PATH_NM,USE_YN,ICON_KND_CD,PSN_INFO_SAFE_YN";
    W_addDataSet(dlt_PgmList, grd_PgmList, searchCol01);
    scwin.setCommonCode(); // 2.1 공통코드
    scwin.setDefaultValue(); // 2.2 기본값 설정
    C_SetGridFocus(grd_PgmList); // 그리드 포커스
    C_initGridViewHeight("grd_PgmList", 105); // 컴포넌트 리사이징
    alert(grd_PgmList.getTotalCol());
};
scwin.setCommonCode = function() {};
scwin.setDefaultValue = function() {
    // 날짜(년월일,년월,년 등과 같이 컴포넌트 기본값은 여기서 셋팅한다.	
};
scwin.selectPgmList_submitdone = function(e) {
    var rsCode = W_getResultCode(e)
    if (rsCode == "S") {
        grd_PgmList.setFocusedCell(0, 0);
    }
}
scwin.updateProgListAll_submitdone = function(e) {
    var rsCode = W_getResultCode(e)
    if (rsCode == "S") {
        C_msgOk("1001");
        dlt_PgmList.reform();
    }
};
scwin.ibx_PrgNm_onchange = function() {
    scbmc.search_onclick();
};
scwin.ibx_ProcUrl_onchange = function() {
    scbmc.search_onclick();
};
scwin.sbx_UseYn_onchange = function() {
    scbmc.search_onclick();
};
scwin.sbx_PsnInpo_onchange = function() {
    scbmc.search_onclick();
};
scwin.preSaveCheck = function(idx) {
    var status = true;
    for (var i = 0; i < idx.length; i++) {
        var rowStatus = dlt_PgmList.getRowStatus(idx[i]);
        if (rowStatus == "C" || rowStatus == "U") {
            if (dlt_PgmList.getCellData(idx[i], "PROGRM_NM") == "") {
                grd_PgmList.setFocusedCell(idx[i], "PROGRM_NM", true);
                C_alert("프로그램명은 필수 입력 값입니다.", "", "", "확인");
                status = false;
                break;
            }
            if (dlt_PgmList.getCellData(idx[i], "PROGRM_PATH_NM") == "") {
                grd_PgmList.setFocusedCell(idx[i], "PROGRM_PATH_NM", true);
                C_alert("프로그램URL은 필수 입력 값입니다.", "", "", "확인");
                status = false;
                break;
            }
            if (dlt_PgmList.getCellData(idx[i], "ICON_KND_CD") == "") {
                grd_PgmList.setFocusedCell(idx[i], "ICON_KND_CD", true);
                C_alert("아이콘 구분은 필수 입력 값입니다.", "", "", "확인");
                status = false;
                break;
            }
        }
    }
    return status;
};
scwin.trigger1_onclick = function(e) {
    alert(grd_PgmList.getTotalHeaderCol({
        mergedColumn: true,
        defaultColumn: true
    }));
};
scwin.checkVal = function() {
    return grd_PgmList.getTotalHeaderCol({
        mergedColumn: true,
        defaultColumn: true
    }) == '16';
}
scwin.unitTest = function() {
    // Init test
    WebSquare.wUnit.start();
    // Test step 1: 1. 샘플파일 실행 후 getTotalHeaderCol 버튼을 클릭한다. - 1. After running the sample file, click the getTotalHeaderCol button.
    // WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()"); -> do automation so not need to click this button
    WebSquare.wUnit.addCommand("pause", "1000");
    // Verify 1. 1. Header의 갯수(16)를 리턴하여 보여준다.(이전에는 기능이 없었음) - 1. Return the number of headers (16) to show (there was no functionality before)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //=============================================================================
    // 1. 변수선언
    //=============================================================================
    scbmc = {};
    //=============================================================================
    // 2. 초기 스크립트 수행 함수 정의
    //=============================================================================
    //=============================================================================
    // 2.1. 공통코드
    //=============================================================================
    //=============================================================================
    // 2.2. 기본값 설정
    //=============================================================================
    //=============================================================================
    // 3.공통버튼정의 
    //=============================================================================		
    /**
     * 조회버튼 클릭시 조건에 따른 프로그램 리스트를 가져온다.
     */
    scbmc.search_onclick = function() {
        C_SetGridFocus(grd_PgmList);
        W_SelectTrans("sbm_selectPgmList", "/co/ca/selectPgmList.do", "dma_Search", "dlt_PgmList",
            "scwin.selectPgmList_submitdone", "", "");
    };
    /**
     * 선택된 그리드의  row를 추가한다.
     */
    scbmc.add_onclick = function() {
        window.insertIndex = "";
        if (W_FocusDataList == dlt_PgmList) {
            dlt_PgmList.insertRow();
        }
    };
    /**
     * 선택된 그리드의  row를 삭제한다.
     */
    scbmc.del_onclick = function() {
        if (W_FocusDataList == dlt_PgmList) {
            //단건 삭제 및 다건 삭제 모두 그리드뷰 컴포넌트를 인자로 보냄..
            //단건일 경우 W_EraserRow(grd_PgmList,"F");
            //다건 일 경우 W_EraserRow(grd_PgmList,"T");
            //멀티 삭제 일 경우 GridView를 함수에 파라메터로 보낸다. 
            W_EraserRow(grd_PgmList, "F");
        }
    };
    /**
     * 모든 그리드의 rowStatus C,U,D,E 상태(Modify)인것만 저장한다.
     */
    scbmc.save_onclick = function() {
        if (!scwin.preSaveCheck(dlt_PgmList.getModifiedIndex())) return;
        W_UpdateTrans("sbm_updateProgListAll", "/co/ca/updateProgListAll.do", "dlt_PgmList", "",
            "scwin.updateProgListAll_submitdone", "", "");
    };
    /**
     * 엑셀 내려받기 
     */
    scbmc.down_onclick = function() {
        return fileName = "프로그램리스트";
    };
    /**
     * 미리보기(출력) 
     */
    scbmc.preView_onclick = function() {};
    /**
     * 결재상신 
     */
    scbmc.appr_onclick = function() {};
    //=============================================================================
    // 4.submitdone(CallBack) 관련함수 
    //   W_getResultCode(e) 의 값 (S:성공, E:에러, W:워닝)
    //=============================================================================
    //프로그램 리스트 submitdone scwin.selectPgmList_submitdone
    //업데이트 submitdone
    //=============================================================================
    // 5.DataList 이벤트 정의 
    //=============================================================================
    /**
     * 데이타가 로드되고 바인딩이 끝났을때.. 
     */
    scbmc.ondataload = function(aDataList) {};
    /**
     * 열이 바뀌기전에 처리할때..
     */
    scbmc.onbeforecelldatachange = function(aDataList, row, colID, oldValue, newValue) {
        return true;
    };
    /**
     * 열이 바뀌고 난 후...
     */
    scbmc.oncelldatachange = function(aDataList, row, colID, oldValue, newValue) {};
    /**
     * 행이 바뀌기전에 처리할때..
     */
    scbmc.onbeforerowpositionchange = function(aDataList, row, oldRow) {
        return true;
    };
    /**
     * 행이 변경된 후..
     */
    scbmc.onrowpositionchange = function(aDataList, row, oldRow) {};
    /**
     * 행 추가 후...
     */
    scbmc.oninsertrow = function(aDataList, row) {
        if (aDataList == dlt_PgmList) {
            W_SelectTrans("sbm_PgmListSeq", "/co/ca/selectPgmListSeq.do", "", "dlt_PgmListSeq", "", "S", "");
            dlt_PgmList.setCellData(row, "PROGRM_SEQ", dlt_PgmListSeq.getCellData(0, "SEQ"));
            dlt_PgmList.setCellData(row, "INQ_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "ADDT_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "INSRT_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "DELETE_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "SAVE_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "PREVEW_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "DOWN_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "SNCT_BTN_USE_YN", 'T');
            dlt_PgmList.setCellData(row, "ICON_KND_CD", 'I');
            dlt_PgmList.setCellData(row, "USE_YN", 'T');
        }
    };
    /**
     * 행 삭제 후...
     */
    scbmc.onremoverow = function(aDataList, row) {};
    //=============================================================================
    // 6.GridView 이벤트 정의 
    //============================================================================= 
    /**
     * 셀의 수정이 끝나서 포커스가 빠져나온 경우...
     */
    scbmc.onafteredit = function(aDataList, aGridView, row, col, value) {};
    /**
     * 선택된 셀이 변경되었을 경우 발생..
     */
    scbmc.oncellindexchange = function(aDataList, aGridView, row, col, oldRow, oldCol) {};
    /**
     * 셀의 에디트가 끝난 경우 발생..
     */
    scbmc.oneditend = function(aDataList, aGridView, row, col, value) {};
    /**
     * 그리드에 포커스가 갔을때 
     */
    scbmc.onsetfocus = function(aDataList, aGridView) {};
    /**
     * 그리드 그룹바이 이벤트
     */
    scbmc.ongroupby = function(aDataList, aGridView, options) {};
    //=============================================================================
    // 7.일반 컴포넌트 이벤트 정의 
    //=============================================================================
    /**
     * 프로그램명 onchange 이벤트
     */
    //=============================================================================
    // 8.사용자 정의 함수 정의 
    //=============================================================================	
    /**
     * 필수 입력 정보를 체크한다.
     */
    // Function test
    // Created by Sang.Do
    // Created date 17-Jan-2018
    window.fileName = undefined;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
